package vn.cinema;
import org.junit.jupiter.api.Test;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.beans.factory.annotation.Autowired;import vn.cinema.app.Application;import vn.cinema.service.NotificationService;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(classes=Application.class)class NotificationTest{@Autowired NotificationService s;@Test void deliveryIsIdempotentAndReadIsOwned(){var n=s.send(100L,71L,"Thanh toán thành công","Vé đã được xác nhận");assertThat(s.send(100L,71L,"Thanh toán thành công","Vé đã được xác nhận").id).isEqualTo(n.id);assertThat(s.list(71,false)).hasSize(1);assertThatThrownBy(()->s.read(n.id,72,false)).hasMessageContaining("quyền");assertThat(s.read(n.id,71,false).readStatus).isTrue();}}
